   919  bool CodeStreamDecompress::read_cbd(uint8_t* headerData, uint16_t header_size)
   920  {
   921     assert(headerData != nullptr);
   922     if(header_size < 2 || (header_size - 2) != getHeaderImage()->numcomps)
   923     {
   924            Logger::logger_.error("Error reading CBD marker");
   925            return false;
   926     }
   927     /* Ncbd */
   928     uint16_t numComps;
   929     grk_read<uint16_t>(headerData, &numComps);
   930     headerData += sizeof(uint16_t);
   931
   932     if(numComps != getHeaderImage()->numcomps)
   933     {
   934            Logger::logger_.error("Error reading CBD marker");
   935            return false;
   936     }
   937
   938     for(uint16_t i = 0; i < getHeaderImage()->numcomps; ++i)
   939     {
   940            /* Component bit depth */
   941            uint8_t comp_def;
   942            grk_read<uint8_t>(headerData++, &comp_def);
   943            auto comp = getHeaderImage()->comps + i;
   944            comp->sgnd = ((uint32_t)(comp_def >> 7U) & 1U);
   945            auto prec = (uint8_t)((comp_def & 0x7f) + 1U);
   946            if(prec > GRK_MAX_SUPPORTED_IMAGE_PRECISION)
   947            {
   948                   Logger::logger_.error("CBD marker: precision %d for component %d is greater than maximum "
   949                                                             "supported precision %d",
   950                                                             prec, i, GRK_MAX_SUPPORTED_IMAGE_PRECISION);
   951                   return false;
   952            }
   953            comp->prec = prec;
   954     }
   955
   956     return true;
   957  }
